package com.parkinglot.service;

import com.parkinglot.entity.Car;
import com.parkinglot.entity.CarAssignment;
import com.parkinglot.entity.ParkingLot;
import com.parkinglot.entity.ParkingSpot;
import org.springframework.test.util.ReflectionTestUtils;

import java.util.UUID;

/**
 * Builds entities for unit tests. IDs are normally generated by the database,
 * so they're set here directly.
 */
final class TestData {

    private TestData() {
    }

    static ParkingLot lot(String name) {
        ParkingLot lot = new ParkingLot(name);
        ReflectionTestUtils.setField(lot, "id", UUID.randomUUID());
        return lot;
    }

    /** A spot in {@code lot}, also added to the lot's spot list. */
    static ParkingSpot spot(ParkingLot lot, String row, int position) {
        ParkingSpot spot = new ParkingSpot(lot, row + position, row, position);
        ReflectionTestUtils.setField(spot, "id", UUID.randomUUID());
        lot.getSpots().add(spot);
        return spot;
    }

    static Car car(String chassisNumber) {
        return new Car(chassisNumber, null, "SUV", null, null, null);
    }

    static CarAssignment parked(Car car, ParkingSpot spot) {
        CarAssignment assignment = new CarAssignment(car, spot);
        ReflectionTestUtils.setField(assignment, "id", UUID.randomUUID());
        return assignment;
    }
}
